package org.jsoup.safety;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.jsoup.Document;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.*;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.parser.Tag;
import org.jsoup.safety.Cleaner;
import org.jsoup.safety.Whitelist;
import org.junit.*;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class Cleaner_clean_TriageGen1Test {

    private Cleaner cleaner;

    @Before
    public void setUp() {
        Whitelist whitelist = new Whititelist();
        cleaner = new Cleaner(whitelist);
    }

    @Test
    public void testClean_NullDirtyDocument_ThrowsNullPointerException() {
        try {
            cleaner.clean(null);
            assert false;
        } catch (NullPointerException e) {
            // Expected
        }
    }

    @Test
    public void testClean_EmptyDirtyDocument_ReturnsEmptyCleanDocument() {
        Document dirtyDocument = Document.createShell("http://example.com");
        Document cleanDocument = cleaner.clean(dirtyDocument);
        assertEquals(0, cleanDocument.body().childNodeSize());
    }

    @Test
    public void testClean_SingleTextNodeDirtyDocument_ReturnsSingleTextNodeCleanDocument() {
        Document dirtyDocument = Document.createShell("http://example.com");
        Element textNode = dirtyDocument.body().appendText("Hello, World!");
        Document cleanDocument = cleaner.clean(dirtyDocument);
        assertEquals(1, cleanDocument.body().childNodeSize());
        assertNotNull(cleanDocument.body().firstChild().text());
    }

    @Test
    public void testClean_MultipleTextNodeDirtyDocument_ReturnsMultipleTextNodeCleanDocument() {
        Document dirtyDocument = Document.createShell("http://example.com");
        Element textNode1 = dirtyDocument.body().appendText("Hello, ");
        Element textNode2 = dirtyDocument.body().appendText("World!");
        Document cleanDocument = cleaner.clean(dirtyDocument);
        assertEquals(2, cleanDocument.body().childNodeSize());
        assertNotNull(cleanDocument.body().firstChild().text());
        assertNotNull(cleanDocument.body().lastChild().text());
    }

    @Test
    public void testClean_EmptyCleanDocument_ReturnsEmptyCleanDocument() {
        Document dirtyDocument = Document.createShell("http://example.com");
        Document cleanDocument = cleaner.clean(dirtyDocument);
        assertEquals(0, cleanDocument.body().childNodeSize());
    }

    @Test
    public void testClean_NullCleanDocument_ReturnsNull() {
        Document dirtyDocument = null;
        Document cleanDocument = cleaner.clean(dirtyDocument);
        assertNull(cleanDocument);
    }

    @After
    public void tearDown() {
        cleaner = null;
    }
}
